mapper.select:
SELECT COUNT(*) FROM creator_task t
LEFT JOIN creator_task_claim c ON c.task_id=t.id AND c.user_id=#{userId}
WHERE t.region=#{region} AND ((t.status=1 AND t.is_deleted=FALSE) OR c.id IS NOT NULL)

mapper.update:
UPDATE app_user
SET points = points + #{points}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{userId}
